/* Generated by Trae Work */
(function () {
  const ACCESS_KEY = "eliminator_auth";

  if (sessionStorage.getItem(ACCESS_KEY) !== "1") {
    window.location.replace("./index.html");
    return;
  }

  const deviceInput = document.getElementById("device");
  const deviceList = document.getElementById("device-list");
  const output = document.getElementById("output");
  const btnGenerate = document.getElementById("btn-generate");
  const btnReroll = document.getElementById("btn-reroll");
  const btnCopy = document.getElementById("btn-copy");
  const btnLogout = document.getElementById("btn-logout");
  const copyMsg = document.getElementById("copy-msg");

  function setMsg(text, type) {
    if (!copyMsg) return;
    copyMsg.textContent = text || "";
    copyMsg.classList.remove("ok", "error");
    if (type) copyMsg.classList.add(type);
  }

  // “All devices” (popular/common list). Users can still type custom names.
  const DEVICES = [
    "iPhone 8",
    "iPhone X",
    "iPhone XR",
    "iPhone 11",
    "iPhone 11 Pro Max",
    "iPhone 12",
    "iPhone 12 Pro Max",
    "iPhone 13",
    "iPhone 13 Pro Max",
    "iPhone 14",
    "iPhone 14 Pro Max",
    "iPhone 15",
    "iPhone 15 Pro Max",
    "iPhone SE (2022)",
    "iPad (9th Gen)",
    "iPad Pro",
    "Samsung Galaxy A12",
    "Samsung Galaxy A32",
    "Samsung Galaxy A52",
    "Samsung Galaxy A72",
    "Samsung Galaxy S10",
    "Samsung Galaxy S20",
    "Samsung Galaxy S21",
    "Samsung Galaxy S22",
    "Samsung Galaxy S23",
    "Samsung Galaxy S24",
    "Samsung Galaxy Note 10",
    "Redmi Note 8",
    "Redmi Note 10",
    "Redmi Note 11",
    "Redmi Note 12",
    "Redmi Note 13",
    "POCO X3",
    "POCO X5",
    "POCO F3",
    "POCO F5",
    "Realme 7",
    "Realme 8",
    "Realme 9",
    "Realme 10",
    "Oppo A16",
    "Oppo A54",
    "Oppo Reno 7",
    "Vivo Y20",
    "Vivo Y21",
    "Infinix Hot 10",
    "Infinix Hot 11",
    "Infinix Note 12",
    "Tecno Spark 7",
    "Tecno Spark 8",
    "OnePlus 7T",
    "OnePlus 8",
    "OnePlus 9",
    "OnePlus 10",
    "Huawei Y9",
    "Huawei P30"
  ];

  if (deviceList) {
    deviceList.innerHTML = DEVICES.map((d) => `<option value="${escapeHtml(d)}"></option>`).join("");
  }

  function escapeHtml(s) {
    return String(s)
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }

  function clamp(n, min, max) {
    return Math.max(min, Math.min(max, n));
  }

  // Deterministic hash -> pseudo random generator
  function hashString(str) {
    let h = 2166136261;
    for (let i = 0; i < str.length; i++) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return h >>> 0;
  }

  function mulberry32(seed) {
    return function () {
      let t = (seed += 0x6d2b79f5);
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function deviceProfile(name) {
    const s = name.toLowerCase();
    // Rough heuristics (not “cheat”), just a way to bias outputs
    let bias = 0;
    let aimStyle = "Balanced";
    if (s.includes("iphone") || s.includes("ipad")) {
      bias += 6;
      aimStyle = "Smooth iOS";
    }
    if (s.includes("s24") || s.includes("s23") || s.includes("s22") || s.includes("s21") || s.includes("s20")) {
      bias += 5;
      aimStyle = "Fast Android";
    }
    if (s.includes("infinix") || s.includes("tecno")) {
      bias -= 2;
      aimStyle = "Stable Android";
    }
    if (s.includes("note") || s.includes("pro max")) {
      bias -= 1; // bigger screen often likes slightly lower scoped sens
    }
    return { bias, aimStyle };
  }

  function generateSensi(deviceName, variant) {
    const baseSeed = hashString(deviceName || "unknown-device");
    const seed = (baseSeed + (variant || 0) * 1337) >>> 0;
    const rnd = mulberry32(seed);
    const { bias, aimStyle } = deviceProfile(deviceName || "");

    const general = clamp(Math.round(120 + rnd() * 70 + bias), 90, 200);
    const redDot = clamp(Math.round(110 + rnd() * 65 + bias), 80, 190);
    const twoX = clamp(Math.round(95 + rnd() * 60 + bias - 2), 70, 180);
    const fourX = clamp(Math.round(85 + rnd() * 55 + bias - 6), 60, 170);
    const awm = clamp(Math.round(55 + rnd() * 45 + bias - 10), 30, 140);
    const freeLook = clamp(Math.round(120 + rnd() * 70 + bias), 70, 200);

    const dpi = clamp(Math.round(520 + rnd() * 160 + bias * 6), 380, 780);
    const fireButton = clamp(Math.round(42 + rnd() * 22), 35, 70);

    return {
      deviceName,
      aimStyle,
      values: {
        General: general,
        "Red Dot": redDot,
        "2x Scope": twoX,
        "4x Scope": fourX,
        AWM: awm,
        "Free Look": freeLook,
        DPI: dpi,
        "Fire Button": `${fireButton}%`
      }
    };
  }

  function formatBlock(s) {
    const lines = [
      "★ ELIMINATOR SENSI GENERATOR ★",
      "",
      `Device: ${s.deviceName || "Unknown"}`,
      `Profile: ${s.aimStyle}`,
      "",
      `General: ${s.values["General"]}`,
      `Red Dot: ${s.values["Red Dot"]}`,
      `2x Scope: ${s.values["2x Scope"]}`,
      `4x Scope: ${s.values["4x Scope"]}`,
      `AWM: ${s.values["AWM"]}`,
      `Free Look: ${s.values["Free Look"]}`,
      "",
      `Suggested DPI: ${s.values["DPI"]}`,
      `Fire Button: ${s.values["Fire Button"]}`,
      "",
      "Tip: If your drag is too strong, lower General/Red Dot by 5–10."
    ];
    return lines.join("\n");
  }

  let variant = 0;
  function doGenerate() {
    const deviceName = String(deviceInput?.value || "").trim();
    if (!deviceName) {
      setMsg("Please enter your device name.", "error");
      deviceInput?.focus();
      return;
    }
    const sensi = generateSensi(deviceName, variant);
    output.value = formatBlock(sensi);
    window.EliminatorAnalytics?.track("sensi_generated");
    setMsg("Generated. You can copy it now.", "ok");
  }

  async function doCopy() {
    const text = String(output?.value || "");
    if (!text) return setMsg("Generate sensi first.", "error");
    try {
      await navigator.clipboard.writeText(text);
      setMsg("Copied ✅", "ok");
    } catch {
      // fallback
      output.focus();
      output.select();
      const ok = document.execCommand("copy");
      setMsg(ok ? "Copied ✅" : "Copy failed. Select and copy manually.", ok ? "ok" : "error");
    }
  }

  btnGenerate?.addEventListener("click", () => {
    variant = 0;
    doGenerate();
  });

  btnReroll?.addEventListener("click", () => {
    variant++;
    doGenerate();
  });

  btnCopy?.addEventListener("click", doCopy);

  btnLogout?.addEventListener("click", () => {
    sessionStorage.removeItem(ACCESS_KEY);
    window.location.replace("./index.html");
  });

  // Auto-generate if user hit Enter on device input
  deviceInput?.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      variant = 0;
      doGenerate();
    }
  });
})();

